import{_ as o,o as e,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Máquinas de IA","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/ai-machines.md","filePath":"pt-BR/guide/ai-machines.md"}'),n={name:"pt-BR/guide/ai-machines.md"};function r(t,a,d,l,m,c){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="maquinas-de-ia" tabindex="-1">Máquinas de IA <a class="header-anchor" href="#maquinas-de-ia" aria-label="Permalink to &quot;Máquinas de IA&quot;">​</a></h1><p>Uma máquina de IA é um computador que roda modelos com o <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a>, como um Mac mini ou uma <a href="#linux">máquina Linux com GPU</a>, e os serve para as suas aplicações. Ela também pode rodar <a href="#runtimes">outro runtime</a> com API compatível com a OpenAI. Ela nunca roda aplicações e nunca fica acessível pela internet: a máquina é que se conecta ao Orbit, e só as aplicações de dentro do cluster podem chamá-la.</p><h2 id="requirements" tabindex="-1">O que você precisa <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;O que você precisa {#requirements}&quot;">​</a></h2><ul><li>Um Mac com Apple silicon, ou uma <a href="#linux">máquina Linux</a>, x86-64 ou arm64, com systemd. O Ollama fica instalado e rodando nela, com pelo menos um modelo baixado, por exemplo <code>ollama pull qwen3:8b</code>.</li><li>A máquina precisa alcançar o endereço do console por HTTPS. Nada é aberto na máquina nem no roteador.</li><li>Um administrador da instalação adiciona a máquina.</li></ul><h2 id="add" tabindex="-1">Adicionar uma máquina <a class="header-anchor" href="#add" aria-label="Permalink to &quot;Adicionar uma máquina {#add}&quot;">​</a></h2><ol><li>Abra <strong>Máquinas de IA → Adicionar máquina</strong>, dê um nome e escolha <strong>Criar comando</strong>.</li><li>No terminal da máquina, rode o comando que o console mostra. Ele vale uma vez, por uma hora. Numa máquina Linux ele instala um serviço do systemd: veja <a href="#linux">Máquinas Linux com GPU</a>. Num Mac ele não precisa de <code>sudo</code>, e: <ul><li>baixa o agente do seu Orbit e confere o SHA-256 antes de rodá-lo;</li><li>troca o token de uso único pela chave da própria máquina, guardada em <code>~/Library/Application Support/Orbit/ai-machine.json</code>;</li><li>instala o agente em <code>~/.orbit-ai/bin</code> como agente do launchd (<code>~/Library/LaunchAgents/com.getcortexlabs.orbit-ai.plist</code>). Assim ele abre no login e volta se parar. O log fica em <code>~/.orbit-ai/logs/orbit-ai.log</code>.</li></ul></li><li>A máquina aparece <strong>Online</strong> com os modelos, o tamanho, a quantização e o que cada um sabe fazer (texto, ferramentas, visão, raciocínio, embeddings).</li></ol><h2 id="use" tabindex="-1">Usar numa aplicação <a class="header-anchor" href="#use" aria-label="Permalink to &quot;Usar numa aplicação {#use}&quot;">​</a></h2><ol><li>Na página da máquina, em <strong>Projetos com acesso</strong>, marque os projetos cujas aplicações podem usá-la e escolha <strong>Salvar projetos</strong>.</li><li>Na aplicação, abra <strong>Variáveis</strong>. Em <strong>Máquinas de IA deste projeto</strong>, escolha a máquina, mantenha o nome <code>OLLAMA_HOST</code> ou troque, e escolha <strong>Usar a máquina</strong>. Adicione <code>OLLAMA_MODEL</code> como variável comum se a aplicação ler essa variável.</li><li>Aplique a mudança e faça o deploy.</li></ol><p>No deploy, a referência vira o endereço do próprio projeto, <code>http://orbit-ai.orbit-system.svc/ai/&lt;máquina&gt;.&lt;projeto&gt;.&lt;segredo&gt;</code>. Ele nunca fica guardado nas variáveis da aplicação e só atende as aplicações daquele projeto:</p><ul><li><strong>Outro projeto</strong> chamando, mesmo com uma cópia, recebe <code>403</code>.</li><li><strong>Tirar um projeto da lista</strong> derruba o endereço dele na hora com <code>403</code>; os outros projetos continuam funcionando. O deploy das aplicações dele falha até o projeto voltar para a lista ou a referência sair.</li><li><strong>A página da máquina</strong> lista as aplicações que se referem a ela, em <strong>Aplicações usando</strong>.</li></ul><p>O Orbit separa os projetos pelo endereço de onde vem a chamada, que é o pod que chama. Por isso o endereço de um projeto atende chamadas das aplicações desse projeto no cluster, e não de um processo rodando na rede do próprio servidor.</p><p>A maioria dos clientes recebe o endereço como URL base:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ollama </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Client</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Client(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OLLAMA_HOST&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reply </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.chat(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OLLAMA_MODEL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">messages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Olá&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}])</span></span></code></pre></div><ul><li><strong>LangChain:</strong> <code>ChatOllama(base_url=os.environ[&quot;OLLAMA_HOST&quot;], model=...)</code>.</li><li><strong>Clientes compatíveis com OpenAI:</strong> use <code>OLLAMA_HOST</code> seguido de <code>/v1</code> como URL base, com qualquer chave de API.</li></ul><p>O que uma aplicação pode fazer:</p><ul><li><strong>Permitido:</strong> gerar, conversar e criar embeddings (<code>/api/generate</code>, <code>/api/chat</code>, <code>/api/embed</code>, <code>/api/embeddings</code>), ler os modelos (<code>/api/tags</code>, <code>/api/show</code>, <code>/api/ps</code>, <code>/api/version</code>) e os caminhos compatíveis com OpenAI <code>/v1/chat/completions</code>, <code>/v1/completions</code>, <code>/v1/embeddings</code>, <code>/v1/models</code> e <code>/v1/responses</code>.</li><li><strong>Recusado com 403:</strong> baixar, enviar, criar, copiar e apagar modelos. Os modelos são gerenciados no Mac.</li><li><strong>Streaming:</strong> a resposta chega enquanto o Ollama escreve. Um pedido pode ter até 64 MiB, o bastante para imagens mandadas a modelos de visão.</li><li><strong>Com o Mac desligado ou dormindo:</strong> a chamada responde <code>503</code> dizendo que a máquina não está conectada. Volta a funcionar assim que o Mac volta, sem mudar nada.</li><li><strong>Só de dentro do cluster:</strong> o mesmo caminho no endereço público do console é recusado.</li></ul><h3 id="shared" tabindex="-1">O endereço compartilhado <a class="header-anchor" href="#shared" aria-label="Permalink to &quot;O endereço compartilhado {#shared}&quot;">​</a></h3><p>As máquinas também têm um endereço para a máquina toda, de antes de os projetos terem o próprio. Qualquer aplicação do cluster que o tenha pode usar a máquina, então prefira as referências. <strong>Mostrar endereço</strong> entrega esse endereço como variáveis prontas, e <strong>Desligar</strong> corta ele quando <strong>Aplicações usando</strong> não mostrar ninguém chamando recentemente. As aplicações que ainda usam passam a receber <code>403</code>, e <strong>Ligar de novo</strong> volta o mesmo endereço.</p><p><strong>Trocar endereços</strong> dá à máquina um novo endereço compartilhado e um novo para cada projeto. Os anteriores param na hora; as aplicações com referência pegam o novo endereço no próximo deploy.</p><h2 id="linux" tabindex="-1">Máquinas Linux com GPU <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Máquinas Linux com GPU {#linux}&quot;">​</a></h2><p>O mesmo comando conecta uma máquina Linux, x86-64 ou arm64, com systemd. Ele descobre o sistema e a arquitetura sozinho, pede <code>sudo</code> e:</p><ul><li>cria o usuário <code>orbit-ai</code> e instala o agente em <code>/var/lib/orbit-ai/bin</code>, com a chave da máquina em <code>/var/lib/orbit-ai/ai-machine.json</code>;</li><li>instala e inicia o serviço <code>orbit-ai</code> do systemd, que roda como esse usuário, sem privilégios, começa no boot e volta se parar. <code>journalctl -u orbit-ai</code> mostra o que ele faz.</li></ul><p>A página da máquina mostra as placas de vídeo, com a memória de cada uma, como o <code>nvidia-smi</code> lista, ao lado do processador e da memória. Todo o resto funciona como num Mac: pools, limites, baixar e remover modelos, métricas e avisos. O agente lê <code>OLLAMA_NUM_PARALLEL</code> e <code>OLLAMA_MODELS</code> do serviço do próprio Ollama no systemd.</p><p>O agente fala com o Ollama em <code>127.0.0.1:11434</code>, onde o instalador do Ollama o deixa. Uma máquina Linux sempre inicia o agente no boot; a escolha entre login e boot, ao adicionar, vale para Macs.</p><h2 id="runtimes" tabindex="-1">Outros runtimes <a class="header-anchor" href="#runtimes" aria-label="Permalink to &quot;Outros runtimes {#runtimes}&quot;">​</a></h2><p>Uma máquina pode servir os modelos com outro runtime além do Ollama, desde que ele tenha uma API compatível com a OpenAI: <a href="https://lmstudio.ai" target="_blank" rel="noreferrer">LM Studio</a>, o <a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">servidor do llama.cpp</a> ou o <a href="https://docs.vllm.ai" target="_blank" rel="noreferrer">vLLM</a>. Conecte a máquina normalmente e depois, na página dela, em <strong>Runtime</strong>, escolha o runtime e <strong>Salvar runtime</strong>. O agente muda em até meio minuto, sem rodar nada na máquina.</p><ul><li><strong>Endereço:</strong> vazio usa onde o runtime costuma atender: <code>http://127.0.0.1:1234</code> no LM Studio, <code>http://127.0.0.1:8080</code> no llama.cpp e <code>http://127.0.0.1:8000</code> no vLLM. Dá para informar outro, sempre da própria máquina: <code>127.0.0.1</code> ou <code>localhost</code> com a porta. O Orbit recusa qualquer outro endereço, e o agente também.</li><li><strong>Modelos:</strong> a lista vem do <code>/v1/models</code> do runtime, só com os nomes. Carregue e remova modelos no runtime; a página acompanha.</li><li><strong>Chamadas:</strong> as aplicações chamam os caminhos em <code>/v1</code>, como <code>/v1/chat/completions</code> e <code>/v1/embeddings</code>, no mesmo endereço de sempre. Os caminhos <code>/api</code>, que são do Ollama, recebem <code>404</code> com uma mensagem dizendo quais caminhos chamar.</li><li><strong>Pools:</strong> um pool pode misturar runtimes. Uma chamada a um caminho <code>/api</code> só vai para as máquinas que rodam Ollama.</li><li><strong>Só no Ollama:</strong> baixar e remover modelos pelo console e o tempo que um modelo fica na memória. A página avisa em vez de oferecer. <strong>Testar um modelo</strong> funciona com todos os runtimes.</li></ul><p>Um agente anterior ao Orbit 0.3.0 só conhece o Ollama. Ele se atualiza sozinho em até uma hora e então muda; a página avisa enquanto isso.</p><h2 id="available" tabindex="-1">Manter disponível <a class="header-anchor" href="#available" aria-label="Permalink to &quot;Manter disponível {#available}&quot;">​</a></h2><h3 id="boot" tabindex="-1">Começar no login ou no boot <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;Começar no login ou no boot {#boot}&quot;">​</a></h3><p>A janela de adicionar oferece dois jeitos de começar:</p><ul><li><strong>No login,</strong> o padrão: o agente começa quando você entra no Mac, sem <code>sudo</code>. Depois de reiniciar, nada volta até alguém entrar no Mac, a não ser que o login automático esteja ligado.</li><li><strong>No boot:</strong> o comando termina com <code>--at-boot</code> e pede a senha do Mac uma vez. <ul><li>Ele instala o agente como daemon do launchd (<code>/Library/LaunchDaemons/com.getcortexlabs.orbit-ai.plist</code>) e o <code>ollama serve</code> como outro (<code>com.getcortexlabs.orbit-ai.ollama.plist</code>). Os dois rodam como o seu usuário, antes de qualquer login.</li><li>Feche o app do Ollama e tire ele de <strong>Ajustes do Sistema → Geral → Itens de Início</strong>, para não abrir uma segunda cópia quando você entrar.</li></ul></li></ul><p>Para mudar como um Mac já conectado começa, escolha <strong>Novo comando de conexão</strong> e rode com a outra opção.</p><h3 id="availability" tabindex="-1">O que a página mostra <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;O que a página mostra {#availability}&quot;">​</a></h3><p><strong>Disponibilidade</strong>, na página da máquina, diz como ela volta depois de reiniciar, do jeito que o Mac informa:</p><ul><li>se começa no login ou no boot;</li><li>o login automático;</li><li>se religa depois de uma falta de energia;</li><li>o repouso do sistema;</li><li>o FileVault.</li></ul><p>Ela avisa sobre cada um que deixaria a máquina offline:</p><ul><li><strong>Começa no login sem login automático:</strong> nada volta depois de reiniciar até alguém entrar.</li><li><strong>Repouso:</strong> um Mac dormindo para de responder. Num Mac mini, ligue <strong>Impedir repouso automático quando a tela estiver desligada</strong> em <strong>Ajustes do Sistema → Energia</strong>.</li><li><strong>Falta de energia:</strong> ligue <strong>Iniciar automaticamente após falta de energia</strong> no mesmo lugar. Só computadores de mesa têm essa opção.</li><li><strong>FileVault:</strong> com ele ligado, um reinício inesperado espera a senha do disco no próprio Mac, e nada começa antes disso, nem no boot.</li></ul><h3 id="keep-alive" tabindex="-1">Manter o modelo na memória <a class="header-anchor" href="#keep-alive" aria-label="Permalink to &quot;Manter o modelo na memória {#keep-alive}&quot;">​</a></h3><p>O Ollama tira um modelo da memória cinco minutos depois da última chamada, e a próxima espera carregar de novo, muitos segundos num modelo grande. <strong>Manter o modelo na memória</strong>, na página da máquina, muda isso para uma hora ou para sempre.</p><p>O Orbit acrescenta isso como <code>keep_alive</code> nas chamadas de gerar, conversar e embeddings que não definem o próprio. Uma chamada que define <code>keep_alive</code> mantém o dela. Os caminhos compatíveis com OpenAI em <code>/v1</code> continuam com o padrão do Ollama.</p><h3 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status {#status}&quot;">​</a></h3><ul><li><strong>Online:</strong> enquanto o agente continua pedindo chamadas ao Orbit.</li><li><strong>Offline:</strong> depois de 75 segundos sem notícia dele.</li><li><strong>Esperando conexão:</strong> até a primeira conexão.</li><li><strong>Quando o Ollama não responde,</strong> a página avisa, e o agente continua conectado.</li></ul><h3 id="agent-updates" tabindex="-1">Atualizações do agente <a class="header-anchor" href="#agent-updates" aria-label="Permalink to &quot;Atualizações do agente {#agent-updates}&quot;">​</a></h3><p>O agente no Mac acompanha o Orbit ao qual está conectado. Depois que o Orbit atualiza, o agente fica sabendo da nova versão no próximo relatório, em até 30 segundos, e se atualiza sozinho:</p><ol><li>Ele baixa o novo agente do Orbit enquanto continua atendendo chamadas, e confere o download com o SHA-256 que o Orbit anuncia.</li><li>Ele para de aceitar chamadas novas e deixa as que estão em andamento terminarem, por até dois minutos. Ele nunca se atualiza no meio de uma chamada que dá para esperar.</li><li>Ele troca o próprio binário e sai, e o launchd inicia a nova versão alguns segundos depois. Aplicações que chamarem nesse intervalo recebem <code>503</code> e podem tentar de novo.</li></ol><p>A página da máquina mostra a versão do agente, com <strong>atualizando para</strong> e a nova versão enquanto a atualização acontece. Quando o download não bate com o checksum ou o binário não pode ser trocado, a versão atual continua rodando, a página diz o motivo e o agente tenta de novo em até uma hora. Um agente antigo demais para falar com este Orbit é recusado, e a página pede para rodar o comando de conexão de novo em <strong>Conexão</strong>.</p><p>Agentes instalados antes do Orbit 0.2.46 não se atualizam sozinhos. A página avisa que há um agente novo; rode o comando de conexão em <strong>Conexão</strong> uma vez e, daí em diante, o agente acompanha o Orbit.</p><h2 id="retries" tabindex="-1">Novas tentativas e respostas conferidas <a class="header-anchor" href="#retries" aria-label="Permalink to &quot;Novas tentativas e respostas conferidas {#retries}&quot;">​</a></h2><p>O Orbit só tenta uma chamada de novo enquanto nada da resposta chegou à aplicação. Depois do primeiro byte ele nunca tenta, porque uma segunda resposta repetiria ou contradiria o que a aplicação já leu.</p><ul><li><strong>Quando:</strong> nenhuma máquina pegou a chamada a tempo, a máquina caiu antes de responder, ou o Ollama respondeu com um erro <code>5xx</code> antes de mandar qualquer coisa.</li><li><strong>Onde:</strong> em outra máquina do pool quando há, ou na mesma máquina depois de um segundo.</li><li><strong>Quantas vezes:</strong> 2. Um pool muda isso em <strong>Tentar de novo quando uma máquina falha</strong>, de nunca a 3.</li><li><strong>O que a aplicação vê:</strong> a resposta traz <code>Orbit-AI-Attempts</code>, com quantas tentativas foram, e <code>Orbit-AI-Machine</code>, com a máquina que respondeu. Quando todas as tentativas falham, a aplicação recebe o último erro.</li></ul><p>O Orbit também confere se a resposta veio inteira:</p><ul><li><strong>Uma resposta em partes que para no meio</strong> termina com mais uma linha, <code>{&quot;error&quot;:&quot;the AI machine stopped in the middle of the answer&quot;}</code>, no formato que o Ollama usa para erros no meio de uma resposta. Nos caminhos compatíveis com a OpenAI é mais um evento <code>data:</code> com o mesmo erro. Uma resposta cortada nunca parece completa.</li><li><strong>Uma resposta de uma vez só</strong> (<code>&quot;stream&quot;: false</code>) fica guardada até estar inteira. Se chega cortada, o Orbit tenta de novo, e responde <code>502</code> quando continua acontecendo.</li></ul><p>Quando uma chamada de uma vez só pede um JSON Schema, o Orbit confere o texto do modelo contra ele. Isso vale para <code>format</code> com um schema em <code>/api/chat</code> e <code>/api/generate</code>, e para <code>response_format</code> com <code>json_schema</code> em <code>/v1/chat/completions</code>. Um texto que não bate é tentado de novo como uma falha. Quando nenhuma tentativa bate, a aplicação recebe <code>422</code> com <code>validationErrors</code> e a última <code>answer</code>. É o que mais ajuda em trabalho de extração, como transformar anúncios em campos.</p><p>Mande <code>Orbit-AI-Validate: off</code> numa chamada para pular a conferência do schema. Se a resposta está certa continua sendo assunto da aplicação: o Orbit só confere o formato. Um schema que aponta para um arquivo ou um endereço não é conferido.</p><h2 id="metrics" tabindex="-1">Uso e velocidade <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Uso e velocidade {#metrics}&quot;">​</a></h2><p>O Orbit conta cada chamada que as aplicações fazem a uma máquina ou a um pool por ele, e os administradores veem os números na página da máquina, em <strong>Uso</strong>, para a última hora, as últimas 24 horas ou os últimos 7 dias:</p><ul><li><strong>Chamadas e erros</strong>, com os tokens lidos e escritos.</li><li><strong>Tokens por segundo</strong> de cada modelo, pelas contagens que o Ollama manda no fim da resposta. Em chamadas compatíveis com a OpenAI que chegam em partes, o Orbit mede a partir do primeiro token.</li><li><strong>Primeiro token:</strong> quanto uma chamada em partes esperou pelas primeiras palavras, em média.</li><li><strong>Ocupação:</strong> quantas chamadas a máquina atendeu ao mesmo tempo, em média, contra o <a href="#pools">limite num pool</a>.</li><li><strong>Projetos:</strong> quais projetos fizeram as chamadas.</li></ul><p>A página de um pool mostra quanto as chamadas esperaram na fila, as que ele recusou com <code>429</code> e quantas cada máquina atendeu.</p><p><strong>Uso por projeto</strong>, na página das máquinas de IA, soma todas as máquinas por projeto e dia nos últimos 7 dias, no <a href="./time-zone">fuso horário</a> que o Orbit usa, para você ver quem usa as máquinas. Só contam as chamadas que geram texto ou embeddings; listar modelos não conta. Os números ficam guardados pelo mesmo tempo das outras métricas, 8 dias.</p><h2 id="try" tabindex="-1">Testar um modelo <a class="header-anchor" href="#try" aria-label="Permalink to &quot;Testar um modelo {#try}&quot;">​</a></h2><p>Administradores podem testar uma máquina pela página dela, sem escrever uma aplicação. <strong>Testar um modelo</strong> lista os modelos que geram texto: escolha um, escreva um prompt e envie com <strong>Enviar</strong> ou Ctrl ou ⌘ + Enter. A resposta aparece enquanto o modelo escreve. Para um modelo que vê imagens, dá para anexar uma imagem de até 10 MB.</p><p>O prompt faz o mesmo caminho da chamada de uma aplicação: Orbit, o agente no Mac, o Ollama e o modelo. Uma resposta prova que o caminho inteiro funciona. Embaixo dela a página mostra:</p><ul><li><strong>Primeiro token:</strong> o tempo entre o envio e as primeiras palavras, medido pelo navegador.</li><li><strong>Tokens por segundo:</strong> a velocidade com que o modelo escreveu, pela contagem do próprio Ollama.</li><li><strong>Respondeu:</strong> a máquina.</li><li><strong>Modelo:</strong> quanto tempo o Ollama levou para carregá-lo, ou que ele já estava na memória.</li></ul><p>Nada é guardado: o prompt e a resposta ficam no seu navegador e somem quando você fecha a página. Quando a máquina está fora do ar, o painel avisa e não envia. Quando ela cai depois que a página abriu, o painel diz em uns dez segundos que o Mac não está conectado. Quando o Mac recebe o prompt mas não responde em um minuto, por exemplo enquanto carrega um modelo grande, o painel avisa e você pode enviar de novo.</p><h2 id="pools" tabindex="-1">Pools de máquinas <a class="header-anchor" href="#pools" aria-label="Permalink to &quot;Pools de máquinas {#pools}&quot;">​</a></h2><p>Quando mais de um Mac serve modelos, um pool coloca todos atrás de um endereço só. As aplicações chamam esse endereço e o Orbit escolhe a máquina de cada chamada.</p><p>Clique em <strong>Criar pool</strong> na página das máquinas de IA, dê um nome e marque as máquinas. Uma máquina pode estar em mais de um pool e continua com o próprio endereço. O endereço do pool, os projetos com acesso, o endereço compartilhado e as <a href="#use">referências em Variáveis</a> funcionam como os de uma máquina, pela página do pool.</p><p>Em cada chamada, o Orbit lê o modelo pedido e olha as máquinas online do pool:</p><ol><li>Só máquinas que têm o modelo recebem a chamada. Quando nenhuma tem, a chamada recebe <code>404</code> com o nome do modelo.</li><li>Uma máquina com o modelo já na memória vem antes de uma que teria que carregar.</li><li>Entre essas, a máquina com mais folga recebe a chamada, e assim as chamadas se espalham pelo pool.</li></ol><p>Uma máquina recebe no máximo <strong>Chamadas ao mesmo tempo num pool</strong> chamadas vindas de pools ao mesmo tempo. Por padrão é o que o Ollama roda em paralelo: o agente lê <code>OLLAMA_NUM_PARALLEL</code> no Mac e usa 1 quando não está definido. Dá para mudar na página da máquina. O endereço da própria máquina não tem limite, porque o Ollama enfileira essas chamadas sozinho.</p><p>Quando todas as máquinas com o modelo estão ocupadas, a chamada espera uma ficar livre, 30 segundos por padrão. <strong>Esperar uma máquina livre por até</strong>, na página do pool, muda isso de 10 segundos a 2 minutos. Quando nenhuma máquina fica livre a tempo, ou já há 64 chamadas esperando, a chamada recebe <code>429</code> com <code>Retry-After</code>, para a aplicação tentar de novo um pouco depois. Quando as máquinas com o modelo estão todas offline, a chamada recebe <code>503</code>.</p><p>Chamadas que não pedem modelo, como <code>/api/tags</code>, <code>/api/ps</code> e <code>/v1/models</code>, respondem com os modelos das máquinas online do pool juntos. A página do pool mostra cada modelo com quantas máquinas têm ele e se alguma tem na memória, além das máquinas online, das vagas livres e das chamadas esperando.</p><h2 id="models" tabindex="-1">Baixar e remover modelos <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Baixar e remover modelos {#models}&quot;">​</a></h2><p>Administradores cuidam dos modelos de uma máquina pela página dela, sem abrir o Terminal do Mac.</p><ul><li><strong>Baixar um modelo:</strong> escreva o nome como aparece em <a href="https://ollama.com/library" target="_blank" rel="noreferrer">ollama.com/library</a>, por exemplo <code>qwen3:8b</code>, e clique em <strong>Baixar</strong>. A página mostra o progresso do Ollama, e o download continua se você fechar a página. <strong>Interromper</strong> encerra o download; o Ollama guarda o que já baixou e continua dali na próxima vez. Uma máquina baixa um modelo por vez, e o modelo novo aparece na lista assim que fica pronto.</li><li><strong>Disco:</strong> a página mostra o espaço livre onde o Ollama guarda os modelos. Quando o Ollama informa um modelo maior que isso, o Orbit interrompe o download e diz quanto ele precisa.</li><li><strong>Remover um modelo:</strong> <strong>Remover</strong>, ao lado do modelo, primeiro mostra quem ainda pode usar ele: as aplicações que usam a máquina e citam o modelo numa variável, e quando uma aplicação pediu ele pela última vez. Aplicações que pedirem um modelo removido recebem <code>404</code> até ele ser baixado de novo.</li></ul><p>O Orbit manda esses comandos pelo próprio canal com o agente. O endereço de uma aplicação continua recusando baixar, remover, criar e copiar modelos com <code>403</code>. Cada download, download interrompido e remoção vai para a <strong>Atividade</strong> com quem fez.</p><p>Um agente anterior ao Orbit 0.3.0 não baixa nem remove modelos. Ele se atualiza sozinho em até uma hora, e a página avisa enquanto isso.</p><h2 id="warnings" tabindex="-1">Avisos <a class="header-anchor" href="#warnings" aria-label="Permalink to &quot;Avisos {#warnings}&quot;">​</a></h2><p>O Orbit <a href="./notifications#warnings">avisa</a> sobre máquinas de IA como faz com servidores. Os avisos aparecem no cartão da máquina e vão para os canais que os seguem:</p><ul><li><strong>Offline:</strong> a máquina está há 10 minutos sem falar com o Orbit. A mensagem dá o motivo mais provável que o Orbit conhece.</li><li><strong>Runtime sem resposta:</strong> o agente está conectado, mas o Ollama, ou o <a href="#runtimes">runtime</a> que você escolheu, não responde há 2 minutos.</li><li><strong>Modelo ausente:</strong> por 5 minutos, um modelo que as aplicações pediram à máquina no último dia não está na lista dela, por exemplo depois de um <code>ollama rm</code> ou de um nome errado na aplicação. O Orbit guarda, por máquina, os modelos pedidos nas próprias chamadas.</li></ul><h2 id="remove" tabindex="-1">Mudar ou remover uma máquina <a class="header-anchor" href="#remove" aria-label="Permalink to &quot;Mudar ou remover uma máquina {#remove}&quot;">​</a></h2><ul><li><p><strong>Novo comando de conexão</strong> cria um comando de uso único novo, para reinstalar o agente ou trocar de Mac. O Mac atual continua funcionando até o novo conectar.</p></li><li><p><strong>Remover pool</strong>, na página de um pool, derruba o endereço do pool na hora. As máquinas continuam com os próprios endereços.</p></li><li><p><strong>Remover máquina</strong> derruba a chave e o endereço dela na hora e tira a máquina dos pools. As chamadas que ela respondia terminam com <code>503</code>, e as que esperavam num pool vão para as outras máquinas. Para desinstalar o agente do Mac:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;gui/$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)/com.getcortexlabs.orbit-ai&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system/com.getcortexlabs.orbit-ai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system/com.getcortexlabs.orbit-ai.ollama</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Library/LaunchDaemons/com.getcortexlabs.orbit-ai.plist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Library/LaunchDaemons/com.getcortexlabs.orbit-ai.ollama.plist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.orbit-ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/LaunchAgents/com.getcortexlabs.orbit-ai.plist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Library/Application Support/Orbit/ai-machine.json&quot;</span></span></code></pre></div><p>As linhas com <code>sudo</code> só são necessárias depois de uma instalação no boot; as que não acham nada avisam e não mudam nada.</p><p>Numa máquina Linux:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-ai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/orbit-ai.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/orbit-ai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> userdel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-ai</span></span></code></pre></div></li></ul><h2 id="ssh-tunnel" tabindex="-1">Vindo de um túnel SSH <a class="header-anchor" href="#ssh-tunnel" aria-label="Permalink to &quot;Vindo de um túnel SSH {#ssh-tunnel}&quot;">​</a></h2><p>Se você chegava ao Ollama com <code>ssh -R</code> até um servidor, adicione a máquina aqui, espere ficar <strong>Online</strong>, aponte a aplicação para o novo endereço e só então pare o túnel. O agente não precisa de chave SSH no servidor.</p><h2 id="stream" tabindex="-1">Stream direto <a class="header-anchor" href="#stream" aria-label="Permalink to &quot;Stream direto {#stream}&quot;">​</a></h2><p>Por padrão o agente consulta o Orbit pelo endereço HTTPS do console e devolve cada resposta em envios a cada 100 milissegundos, mais ou menos. Isso funciona em qualquer rede. Com mais de uma máquina, ou quando cada milissegundo até o primeiro token conta, administradores podem ligar o <strong>Stream direto</strong> em <strong>Conexão das máquinas</strong>, na página das máquinas de IA.</p><p>Com ele ligado, cada máquina mantém uma conexão permanente com o Orbit:</p><ul><li><strong>A chamada chega na hora,</strong> empurrada pelo stream em vez de esperar uma consulta.</li><li><strong>Os tokens saem assim que o modelo escreve,</strong> sem lotes e sem uma requisição nova por lote.</li><li><strong>O Ollama para na hora</strong> quando a aplicação desiste, em vez de no próximo envio.</li></ul><p>O que ligar muda:</p><ul><li><strong>A porta 7444 abre nos servidores de entrada,</strong> fora do proxy, pelo balanceador do cluster. As conexões seguem, ainda criptografadas, para o Orbit ativo, que escuta por elas na porta 7445 do próprio servidor. Com <a href="./servers">mais de um servidor</a>, a porta acompanha o Orbit ativo.</li><li><strong>A porta só fala TLS 1.3 com certificado de cliente.</strong> O Orbit assina um para cada máquina com a CA dos agentes quando a máquina conecta. Uma máquina conectada antes do Orbit 0.3.0 pede o certificado assim que o agente dela se atualiza. Só uma máquina com o próprio certificado passa do aperto de mão, e remover uma máquina fecha o stream dela e encerra o certificado.</li><li><strong>O firewall do provedor é você quem abre.</strong> Se há um firewall ou uma lista de segurança na frente dos servidores, como na Oracle Cloud, libere a entrada TCP 7444 lá.</li></ul><p>A máquina continua só fazendo conexões de saída. Uma que não alcança a porta segue em HTTPS e tenta o stream de novo sozinha. A página dela mostra <strong>Conexão com o Orbit</strong> e, quando o stream não abriu, o que o agente disse. Quando um stream cai, as chamadas em andamento terminam por HTTPS.</p><p><strong>Endereço que as máquinas discam</strong> é o endereço do console, a não ser que você defina outro. Use o nome ou o IP de um servidor de entrada quando o console fica atrás de um proxy que só passa portas web, como o da Cloudflare.</p><p>Desligar o stream fecha a porta e todos os streams. As máquinas seguem em HTTPS.</p><h2 id="how" tabindex="-1">Como funciona <a class="header-anchor" href="#how" aria-label="Permalink to &quot;Como funciona {#how}&quot;">​</a></h2><p>O agente nunca escuta na rede. Ele pede chamadas ao Orbit pelo endereço HTTPS do console, executa cada uma no Ollama em <code>127.0.0.1:11434</code>, ou no runtime que você escolheu na própria máquina, e devolve a resposta em envios curtos, mais ou menos a cada 100 milissegundos. Assim gerações longas sobrevivem aos limites de tempo do proxy. Dentro do cluster, o serviço <code>orbit-ai</code> em <code>orbit-system</code> aponta para o Orbit ativo, que entrega cada chamada à máquina. Com <a href="./servers">mais de um servidor</a>, os dois acompanham o Orbit ativo.</p>`,96)])])}const h=o(n,[["render",r]]);export{u as __pageData,h as default};
